parameters.functionCode:
// Anti-spam deduplication & header cleanup
const item = items[0].json;
const subject = item.subject || '';
const from = item.from || '';
const text = item.text || item.html || '';

// Basic spam filter
if (!subject || subject.toLowerCase().includes('unsubscribe') || subject.toLowerCase().includes('marketing')) {
  return [];
}

return [{
  json: {
    subject: subject,
    from_email: from,
    body: text.substring(0, 4000),
    received_at: new Date().toISOString()
  }
}];

parameters.jsonBody:
={
  "contents": [
    {
      "role": "user",
      "parts": [
        {
          "text": "Analyze this bank complaint email and output strict JSON with keys: type (complaint/inquiry/spam), bank_name, branch_name, branch_location (city), customer_name, customer_mobile, customer_email, machine_type (ATM/CDM/POS/Kiosk/Server), machine_model, machine_serial_no, warranty_hint (in_warranty/out_of_warranty), customer_ref_no (any ticket or ref code), urgency (high/medium/low), issue_summary (concise one line summary).\n\nSubject: " + $json.subject + "\nSender: " + $json.from_email + "\nBody:\n" + $json.body
        }
      ]
    }
  ],
  "generationConfig": {
    "temperature": 0.1,
    "response_mime_type": "application/json"
  }
}

parameters.functionCode:
const response = items[0].json;
const candidateText = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let extracted = {};
try {
  extracted = JSON.parse(candidateText);
} catch (e) {
  extracted = {
    type: 'complaint',
    issue_summary: 'Unable to parse JSON from AI, manual review required'
  };
}

return [{
  json: {
    is_complaint: (extracted.type === 'complaint'),
    extracted_data: extracted,
    original_subject: $('Anti-Spam & Payload Clean').item.json.subject,
    original_body: $('Anti-Spam & Payload Clean').item.json.body,
    from_email: $('Anti-Spam & Payload Clean').item.json.from_email
  }
}];

// Non-complaint logger or auto-reply trigger
return [{
  json: {
    status: 'archived',
    reason: 'Non-complaint or inquiry',
    email: $json.from_email
  }
}];
